import{_ as a,o as e,c as r,ae as n}from"./chunks/framework.B2ul6ABY.js";const h=JSON.parse('{"title":"Transport & Infrastructure Module","description":"","frontmatter":{},"headers":[],"relativePath":"modules/transport.md","filePath":"modules/transport.md"}'),s={name:"modules/transport.md"};function o(i,t,d,c,l,u){return e(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="transport-infrastructure-module" tabindex="-1">Transport &amp; Infrastructure Module <a class="header-anchor" href="#transport-infrastructure-module" aria-label="Permalink to &quot;Transport &amp; Infrastructure Module&quot;">​</a></h1><p>The transport-infrastructure module ingests data from the Transportation Safety Board (TSB), Transport Canada, the Canadian Transportation Agency (CTA), the Canada Infrastructure Bank (CIB), and Infrastructure Canada. It powers the <code>query_gov_data</code> MCP tool.</p><h2 id="module-transport-infrastructure" tabindex="-1">Module: transport-infrastructure <a class="header-anchor" href="#module-transport-infrastructure" aria-label="Permalink to &quot;Module: transport-infrastructure&quot;">​</a></h2><h3 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Source</th><th>Format</th><th>Description</th><th>Frequency</th></tr></thead><tbody><tr><td><strong>TSB Occurrences</strong></td><td>CSV</td><td>Transportation Safety Board — air, rail, marine, pipeline occurrences</td><td>monthly</td></tr><tr><td><strong>Transport Canada Safety Recalls</strong></td><td>CSV</td><td>Vehicle recalls, compliance violations, enforcement actions</td><td>weekly</td></tr><tr><td><strong>CTA Rulings</strong></td><td>HTML</td><td>Canadian Transportation Agency decisions and rulings</td><td>weekly</td></tr><tr><td><strong>CIB Projects</strong></td><td>HTML</td><td>Canada Infrastructure Bank — investments, projects ($35B+ mandate)</td><td>quarterly</td></tr><tr><td><strong>Infrastructure Canada</strong></td><td>CSV</td><td>Federal infrastructure funding programs, project data</td><td>monthly</td></tr></tbody></table><h3 id="tsb-occurrence-data" tabindex="-1">TSB Occurrence Data <a class="header-anchor" href="#tsb-occurrence-data" aria-label="Permalink to &quot;TSB Occurrence Data&quot;">​</a></h3><p>The TSB tracks all transportation occurrences in Canada:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Data</th></tr></thead><tbody><tr><td><strong>Air</strong></td><td>Aircraft accidents, incidents by type, location, operator, severity</td></tr><tr><td><strong>Rail</strong></td><td>Train derailments, crossings accidents, dangerous goods releases</td></tr><tr><td><strong>Marine</strong></td><td>Shipping accidents, groundings, collisions, fires</td></tr><tr><td><strong>Pipeline</strong></td><td>Pipeline ruptures, leaks, failures, dangerous commodity releases</td></tr></tbody></table><p>Each occurrence includes: date, location, operator, occurrence type, consequences (injuries, fatalities, damage), investigation classification, and safety recommendations.</p><h3 id="transport-canada-safety-data" tabindex="-1">Transport Canada Safety Data <a class="header-anchor" href="#transport-canada-safety-data" aria-label="Permalink to &quot;Transport Canada Safety Data&quot;">​</a></h3><ul><li>Vehicle recalls by make, model, year, component</li><li>Compliance and enforcement actions</li><li>Motor carrier safety ratings</li><li>Dangerous goods incident reports</li></ul><h3 id="canada-infrastructure-bank" tabindex="-1">Canada Infrastructure Bank <a class="header-anchor" href="#canada-infrastructure-bank" aria-label="Permalink to &quot;Canada Infrastructure Bank&quot;">​</a></h3><p>The CIB has a $35B+ mandate to invest in Canadian infrastructure:</p><table tabindex="0"><thead><tr><th>Sector</th><th>Types</th></tr></thead><tbody><tr><td><strong>Green Infrastructure</strong></td><td>Renewable energy, energy storage, smart grids</td></tr><tr><td><strong>Transport</strong></td><td>Transit, rail, highways, bridges</td></tr><tr><td><strong>Water/Wastewater</strong></td><td>Treatment plants, distribution systems</td></tr><tr><td><strong>Trade/Transport</strong></td><td>Ports, airports, logistics hubs</td></tr></tbody></table><p>Data includes project name, location, investment amount, sector, status, and expected outcomes.</p><h2 id="module-structure" tabindex="-1">Module Structure <a class="header-anchor" href="#module-structure" aria-label="Permalink to &quot;Module Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packages/pipeline-core/src/ingestion/transport-infrastructure/</span></span>
<span class="line"><span>  constants.ts  — TSB URLs, TC API configs, CIB URL templates</span></span>
<span class="line"><span>  types.ts      — TransportRecord, TsbOccurrence, TcRecall, CIBProject</span></span>
<span class="line"><span>  fetcher.ts    — CSV fetchers + HTML scrapers</span></span>
<span class="line"><span>  parser.ts     — CSV parsing + normalization</span></span>
<span class="line"><span>  index.ts      — ingestAllTransport(), searchTransport()</span></span></code></pre></div><h2 id="key-functions" tabindex="-1">Key Functions <a class="header-anchor" href="#key-functions" aria-label="Permalink to &quot;Key Functions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>ingestTsbOccurrences()</code></td><td>Fetch and parse TSB occurrence CSVs</td></tr><tr><td><code>ingestTcSafety()</code></td><td>Fetch Transport Canada recall data</td></tr><tr><td><code>ingestCtaRulings()</code></td><td>Scrape CTA decision registry</td></tr><tr><td><code>ingestAllTransport()</code></td><td>Run all transport ingestion</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Transportation safety</strong>: Track plane crashes, train derailments, and pipeline incidents</li><li><strong>Infrastructure monitoring</strong>: Follow CIB investments and project status</li><li><strong>Vehicle safety</strong>: Monitor TC recalls by make/model</li><li><strong>Regulatory oversight</strong>: Review CTA rulings on passenger rights, accessibility</li><li><strong>Government spending</strong>: Track federal infrastructure funding to ridings</li></ul><h2 id="example-queries-for-ai-agents" tabindex="-1">Example Queries for AI Agents <a class="header-anchor" href="#example-queries-for-ai-agents" aria-label="Permalink to &quot;Example Queries for AI Agents&quot;">​</a></h2><ul><li><em>&quot;Find TSB rail derailments involving dangerous goods in 2024&quot;</em></li><li><em>&quot;What are the latest Transport Canada vehicle recalls?&quot;</em></li><li><em>&quot;Show me Canada Infrastructure Bank projects in Ontario&quot;</em></li><li><em>&quot;Search for CTA rulings on airline passenger compensation&quot;</em></li><li><em>&quot;Find TSB air accident investigation reports from 2024&quot;</em></li><li><em>&quot;What federal infrastructure projects are funded in British Columbia?&quot;</em></li></ul>`,23)])])}const g=a(s,[["render",o]]);export{h as __pageData,g as default};
